// PadV3GradReplicate AscendC kernel — replication padding backward
// Supports float32, float16, bfloat16
// Algorithm: scatter-add grad_output rows into grad_input with clamp mapping

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

// =========================================================================
// PadV3GradReplicate kernel — per-(n,c) scatter-add
// =========================================================================

template <typename dataType>
class PadV3GradReplicateKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR grad_output, GM_ADDR grad_input,
        int32_t totalNc, int32_t H, int32_t W, int32_t outH, int32_t outW,
        int32_t pt, int32_t pb, int32_t pl, int32_t pr,
        int32_t blockNum, int32_t ncPerBlock)
    {
        this->totalNc = totalNc;
        this->H = H;
        this->W = W;
        this->outH = outH;
        this->outW = outW;
        this->pt = pt;
        this->pb = pb;
        this->pl = pl;
        this->pr = pr;
        this->ncPerBlock = ncPerBlock;
        this->blockNum = blockNum;

        goGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(grad_output),
            static_cast<uint64_t>(totalNc) * outH * outW);
        giGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ dataType *>(grad_input),
            static_cast<uint64_t>(totalNc) * H * W);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx();
            for (int localIdx = 0; localIdx < ncPerBlock; ++localIdx) {
                int nc = coreIdx * ncPerBlock + localIdx;
                if (nc >= totalNc) { break; }
                ProcessNc(nc);
            }
        }
    }

private:
    __aicore__ inline void InitAivBuffers()
    {
        // Data queues: read gi row, read go row, write gi row
        pipe.InitBuffer(giInQueue_, BUFFER_NUM, W * sizeof(dataType));
        pipe.InitBuffer(goInQueue_, BUFFER_NUM, outW * sizeof(dataType));
        pipe.InitBuffer(giOutQueue_, BUFFER_NUM, W * sizeof(dataType));

        // FP32 intermediate buffers (always needed for reduction and cast)
        pipe.InitBuffer(giFp32Buf_, W * sizeof(float));
        pipe.InitBuffer(goFp32Buf_, outW * sizeof(float));
        pipe.InitBuffer(interiorBuf_, W * sizeof(float));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe.InitBuffer(reduceTmp_, 2 * static_cast<uint32_t>(outW) * sizeof(uint8_t));
        pipe.InitBuffer(padValBuf_, sizeof(float));

        // FP16/BF16 cast buffers
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(giCastBuf_, W * sizeof(float));
            pipe.InitBuffer(goCastBuf_, outW * sizeof(float));
        }
    }

    // Copy gi row from GM → UB (to initialize / accumulate)
    __aicore__ inline void CopyInGi(uint64_t nc, int32_t h)
    {
        giInLocal_ = giInQueue_.AllocTensor<dataType>();
        auto gmOffset = nc * static_cast<uint64_t>(H) * W + static_cast<uint64_t>(h) * W;
        LoadGmToUb(giInLocal_, giGM_[gmOffset], static_cast<uint32_t>(W));
        giInQueue_.EnQue(giInLocal_);
    }

    // Copy go row from GM → UB
    __aicore__ inline void CopyInGo(uint64_t nc, int32_t oh)
    {
        goInLocal_ = goInQueue_.AllocTensor<dataType>();
        auto gmOffset = nc * static_cast<uint64_t>(outH) * outW + static_cast<uint64_t>(oh) * outW;
        LoadGmToUb(goInLocal_, goGM_[gmOffset], static_cast<uint32_t>(outW));
        goInQueue_.EnQue(goInLocal_);
    }

    // Write accumulated gi row UB → GM
    __aicore__ inline void CopyOutGi(uint64_t nc, int32_t h)
    {
        giOutLocal_ = giOutQueue_.DeQue<dataType>();
        auto gmOffset = nc * static_cast<uint64_t>(H) * W + static_cast<uint64_t>(h) * W;
        StoreUbToGm(giGM_[gmOffset], giOutLocal_, static_cast<uint32_t>(W));
        giOutQueue_.FreeTensor(giOutLocal_);
    }

    // Prepare fp32 tensor from input (cast if needed)
    __aicore__ inline void PrepareFp32Input(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            AscendC::LocalTensor<float> castTmp = giCastBuf_.Get<float>();
            AscendC::Cast(castTmp, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
            dst = castTmp;
        }
    }

    // Cast fp32 → output dtype if needed
    __aicore__ inline void FinalizeOutput(
        AscendC::LocalTensor<dataType> &out,
        AscendC::LocalTensor<float> &src,
        int32_t count)
    {
        if constexpr (!std::is_same_v<dataType, float>) {
            AscendC::Cast(out, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
        }
    }

    // Prepare fp32 go tensor (use dedicated cast buffer)
    __aicore__ inline void PrepareFp32GoInput(
        AscendC::LocalTensor<float> &dst,
        AscendC::LocalTensor<dataType> &src,
        int32_t count)
    {
        if constexpr (std::is_same_v<dataType, float>) {
            dst = src.template ReinterpretCast<float>();
        } else {
            goFp32Local_ = goCastBuf_.Get<float>();
            AscendC::Cast(goFp32Local_, src, AscendC::RoundMode::CAST_NONE, count);
            AscendC::PipeBarrier<PIPE_V>();
            dst = goFp32Local_;
        }
    }

    // Add interior: gi[h, 0:W] += go[oh, pl:pl+W]
    __aicore__ inline void AddInterior(int32_t /*pl*/)
    {
        interiorLocal_ = interiorBuf_.Get<float>();

        // giFp32Local_ already set from DeQue, goFp32 already set
        // Copy interior section of go: go[oh, pl:pl+W] → interiorLocal
        AscendC::DataCopyExtParams copyParams{
            1, static_cast<uint32_t>(W) * sizeof(float),
            static_cast<uint32_t>(pl) * sizeof(float), 0, 0};
        AscendC::DataCopy(interiorLocal_, goFp32Local_, copyParams);

        // Vector add: giFp32 += interior
        AscendC::Add(giFp32Local_, giFp32Local_, interiorLocal_, W);
    }

    // Accumulate left pad: gi[h, 0] += sum(go[oh, 0:pl])
    __aicore__ inline void AddLeftPad()
    {
        if (pl <= 0) { return; }

        reduceTmpLocal_ = reduceTmp_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();

        // Copy left pad region to temporary for reduction
        AscendC::DataCopyExtParams copyParams{
            1, static_cast<uint32_t>(pl) * sizeof(float), 0, 0, 0};
        AscendC::DataCopy(interiorLocal_, goFp32Local_, copyParams);

        AscendC::ReduceSum<float>(sumLocal_, interiorLocal_, reduceTmpLocal_, pl);
        AscendC::PipeBarrier<PIPE_V>();

        float padSum = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Add to giFp32Local_[0]
        AscendC::LocalTensor<float> gi0 = giFp32Local_;
        float gi0Val = gi0.GetValue(0);
        gi0.SetValue(0, gi0Val + padSum);
    }

    // Accumulate right pad: gi[h, W-1] += sum(go[oh, pl+W:outW])
    __aicore__ inline void AddRightPad()
    {
        if (pr <= 0) { return; }

        reduceTmpLocal_ = reduceTmp_.Get<uint8_t>();
        sumLocal_ = sumBuf_.Get<float>();

        // Copy right pad region
        AscendC::DataCopyExtParams copyParams{
            1, static_cast<uint32_t>(pr) * sizeof(float),
            static_cast<uint32_t>(pl + W) * sizeof(float), 0, 0};
        AscendC::DataCopy(interiorLocal_, goFp32Local_, copyParams);

        AscendC::ReduceSum<float>(sumLocal_, interiorLocal_, reduceTmpLocal_, pr);
        AscendC::PipeBarrier<PIPE_V>();

        float padSum = sumLocal_.GetValue(0);
        AscendC::PipeBarrier<PIPE_ALL>();

        float giLast = giFp32Local_.GetValue(W - 1);
        giFp32Local_.SetValue(W - 1, giLast + padSum);
    }

    // Compute accumulation for one go row into gi row
    __aicore__ inline void ComputeAccumulate()
    {
        goInLocal_ = goInQueue_.DeQue<dataType>();
        PrepareFp32GoInput(goFp32Local_, goInLocal_, outW);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Interior section: gi[h,:] += go[oh, pl:pl+W]
        AddInterior(pl);

        // Left padding edge: gi[h,0] += sum(go[oh, :pl])
        AddLeftPad();

        // Right padding edge: gi[h, W-1] += sum(go[oh, pl+W:])
        AddRightPad();

        goInQueue_.FreeTensor(goInLocal_);
        AscendC::PipeBarrier<PIPE_ALL>();
    }

    // Process one gi row: load gi row, accumulate all go contributions, write back
    __aicore__ inline void ProcessGiRow(uint64_t nc, int32_t h, int32_t ohStart, int32_t ohEnd)
    {
        // Step 1: Load gi row from GM (as accumulator)
        CopyInGi(nc, h);

        // DeQue and prepare fp32 accumulator
        giInLocal_ = giInQueue_.DeQue<dataType>();
        PrepareFp32Input(giFp32Local_, giInLocal_, W);
        giInQueue_.FreeTensor(giInLocal_);
        AscendC::PipeBarrier<PIPE_ALL>();

        // Step 2: Accumulate all contributing go rows
        for (int oh = ohStart; oh <= ohEnd; ++oh) {
            CopyInGo(nc, oh);
            ComputeAccumulate();
        }

        // Step 3: Write back accumulated gi row to GM
        giOutLocal_ = giOutQueue_.AllocTensor<dataType>();
        if constexpr (std::is_same_v<dataType, float>) {
            // Direct copy (giFp32Local_ IS giOutLocal_ for fp32 via ReinterpretCast)
            AscendC::DataCopyExtParams copyParams{
                1, static_cast<uint32_t>(W) * sizeof(float), 0, 0, 0};
            AscendC::DataCopy(giOutLocal_, giFp32Local_, copyParams);
        } else {
            FinalizeOutput(giOutLocal_, giFp32Local_, W);
        }
        giOutQueue_.EnQue(giOutLocal_);

        CopyOutGi(nc, h);
    }

    // Process a single (n,c) pair
    __aicore__ inline void ProcessNc(int32_t nc)
    {
        uint64_t nc64 = static_cast<uint64_t>(nc);

        // Process all gi rows
        for (int h = 0; h < H; ++h) {
            int ohStart, ohEnd;
            if (h == 0) {
                // Top edge: go rows 0..pt all map to gi row 0
                ohStart = 0;
                ohEnd = pt;
            } else if (h == H - 1) {
                // Bottom edge: go rows pt+H-1..outH-1 all map to gi row H-1
                ohStart = pt + H - 1;
                ohEnd = outH - 1;
            } else {
                // Interior: exactly one go row maps to gi row h
                ohStart = pt + h;
                ohEnd = pt + h;
            }

            ProcessGiRow(nc64, h, ohStart, ohEnd);
        }
    }

private:
    int32_t totalNc = 0;
    int32_t H = 0;
    int32_t W = 0;
    int32_t outH = 0;
    int32_t outW = 0;
    int32_t pt = 0;
    int32_t pb = 0;
    int32_t pl = 0;
    int32_t pr = 0;
    int32_t ncPerBlock = 0;
    int32_t blockNum = 0;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> goGM_;
    AscendC::GlobalTensor<dataType> giGM_;

    // TQue for GM↔UB data transfer
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> giInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> goInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> giOutQueue_;

    // TBuf for intermediate computation
    AscendC::TBuf<AscendC::TPosition::VECCALC> giFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> goFp32Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> interiorBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceTmp_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> padValBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> giCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> goCastBuf_;

    // Local tensor handles
    AscendC::LocalTensor<dataType> giInLocal_;
    AscendC::LocalTensor<dataType> goInLocal_;
    AscendC::LocalTensor<dataType> giOutLocal_;
    AscendC::LocalTensor<float> giFp32Local_;
    AscendC::LocalTensor<float> goFp32Local_;
    AscendC::LocalTensor<float> interiorLocal_;
    AscendC::LocalTensor<float> sumLocal_;
    AscendC::LocalTensor<uint8_t> reduceTmpLocal_;
};

// =========================================================================
// Kernel entry point with dtype dispatch
// =========================================================================

extern "C" __global__ __aicore__ void pad_v3_grad_replicate(
    GM_ADDR grad_output, GM_ADDR grad_input,
    int32_t totalNc, int32_t H, int32_t W, int32_t outH, int32_t outW,
    int32_t pt, int32_t pb, int32_t pl, int32_t pr,
    int32_t blockNum, int32_t ncPerBlock,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        PadV3GradReplicateKernel<float> kernel;
        kernel.Init(grad_output, grad_input, totalNc, H, W, outH, outW, pt, pb, pl, pr,
                    blockNum, ncPerBlock);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        PadV3GradReplicateKernel<half> kernel;
        kernel.Init(grad_output, grad_input, totalNc, H, W, outH, outW, pt, pb, pl, pr,
                    blockNum, ncPerBlock);
        kernel.Process();
    } else {
        PadV3GradReplicateKernel<bfloat16_t> kernel;
        kernel.Init(grad_output, grad_input, totalNc, H, W, outH, outW, pt, pb, pl, pr,
                    blockNum, ncPerBlock);
        kernel.Process();
    }
}
