// PadV3GradReplicate op_host — tiling + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_pad_v3_grad_replicate.h"

constexpr int32_t DEFAULT_NUM_CORES = 20;

namespace ascend_kernel {

at::Tensor pad_v3_grad_replicate(
    const at::Tensor &grad_output,
    at::IntArrayRef ge_padding)
{
    // Input validation
    TORCH_CHECK(grad_output.dim() == 4,
        "grad_output must be 4D NCHW");
    TORCH_CHECK(
        grad_output.scalar_type() == at::kFloat ||
            grad_output.scalar_type() == at::kHalf ||
            grad_output.scalar_type() == at::kBFloat16,
        "grad_output must be float16, float32, or bfloat16");
    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");
    TORCH_CHECK(ge_padding.size() == 8,
        "ge_padding must be length 8: [N0,N1,C0,C1,pt,pb,pl,pr]");

    // Extract params
    int32_t N = static_cast<int32_t>(grad_output.sizes()[0]);
    int32_t C = static_cast<int32_t>(grad_output.sizes()[1]);
    int32_t outH = static_cast<int32_t>(grad_output.sizes()[2]);
    int32_t outW = static_cast<int32_t>(grad_output.sizes()[3]);

    int32_t pt = static_cast<int32_t>(ge_padding[4]);
    int32_t pb = static_cast<int32_t>(ge_padding[5]);
    int32_t pl = static_cast<int32_t>(ge_padding[6]);
    int32_t pr = static_cast<int32_t>(ge_padding[7]);

    int32_t H = outH - pt - pb;
    int32_t W = outW - pl - pr;
    TORCH_CHECK(H > 0 && W > 0, "invalid padding: H=", H, " W=", W);

    int32_t totalNc = N * C;

    // Block-level tiling
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
    if (coreNum <= 0) { coreNum = DEFAULT_NUM_CORES; }

    int32_t usedCoreNum = std::min<int32_t>(coreNum, totalNc);
    if (usedCoreNum <= 0) { usedCoreNum = 1; }
    int32_t ncPerBlock = (totalNc + usedCoreNum - 1) / usedCoreNum;

    // Allocate output
    auto options = grad_output.options();
    at::Tensor grad_input = at::zeros({N, C, H, W}, options);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (grad_output.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (grad_output.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All params as left values for EXEC_KERNEL_CMD
    int32_t blockNum = usedCoreNum;
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(pad_v3_grad_replicate, blockDim,
                    grad_output, grad_input,
                    totalNc, H, W, outH, outW,
                    pt, pb, pl, pr,
                    blockNum, ncPerBlock,
                    dtypeFlag);

    return grad_input;
}

}  // namespace ascend_kernel
