    """F.pad replicate with custom backward that works on any device."""

    @staticmethod
    def forward(ctx, input_tensor, pad_tuple):
        # pad_tuple: (left, right, top, bottom) for 4D NCHW
        ctx.pad = pad_tuple
        # Compute forward on CPU (supports replicate)
        cpu_result = _ORIG_F_PAD(
            input_tensor.cpu(), pad_tuple, mode="replicate")
        return cpu_result.to(input_tensor.device)

    @staticmethod
    def backward(ctx, grad_output):
        pad = ctx.pad
        pl, pr, pt, pb = [int(p) for p in pad]
        N, C, outH, outW = grad_output.shape
        H = outH - pt - pb
        W = outW - pl - pr
        dtype = grad_output.dtype
        device = grad_output.device

        go = grad_output.to(torch.float32)
        gi = torch.zeros(N, C, H, W, dtype=torch.float32, device=device)

        for oh in range(outH):
            h = max(0, min(oh - pt, H - 1))
            go_row = go[:, :, oh, :]
            gi[:, :, h, :] += go_row[:, :, pl:pl + W]
            if pl > 0:
                gi[:, :, h, 0] += go_row[:, :, :pl].sum(dim=-1)
            if pr > 0:
                gi[:, :, h, W - 1] += go_row[:, :, pl + W:].sum(dim=-1)

        return gi.to(dtype), None


def _patched_pad(input_tensor, pad, mode="constant", value=None):
    if mode == "replicate":
        return _ReplicatePadBackward.apply(input_tensor, pad)
    return _ORIG_F_PAD(input_tensor, pad, mode=mode, value=value)


F.pad = _patched_pad


