11	// PadV3GradReplicate AscendC kernel — replication padding backward
12	// Supports float32, float16, bfloat16
13	// Algorithm: scatter-add grad_output rows into grad_input with clamp mapping
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 2;
18	
19	// ---------------------------------------------------------------------------
20	// Inline helpers
21	// ---------------------------------------------------------------------------
22	
23	template <typename T>
24	__aicore__ inline void LoadGmToUb(
25	    AscendC::LocalTensor<T> &dst,
26	    AscendC::GlobalTensor<T> src,
27	    uint32_t count)
28	{
29	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
30	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
31	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
32	}
33	
34	template <typename T>
35	__aicore__ inline void StoreUbToGm(
36	    AscendC::GlobalTensor<T> dst,
37	    AscendC::LocalTensor<T> &src,
38	    uint32_t count)
39	{
40	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
41	    AscendC::DataCopyPad(dst, src, copyParams);
42	}
43	
44	// =========================================================================
45	// PadV3GradReplicate kernel — per-(n,c) scatter-add
46	// =========================================================================
47	
48	template <typename dataType>
49	class PadV3GradReplicateKernel {
50	public:
51	    __aicore__ inline void Init(
52	        GM_ADDR grad_output, GM_ADDR grad_input,
53	        int32_t totalNc, int32_t H, int32_t W, int32_t outH, int32_t outW,
54	        int32_t pt, int32_t pb, int32_t pl, int32_t pr,
55	        int32_t blockNum, int32_t ncPerBlock)
56	    {
57	        this->totalNc = totalNc;
58	        this->H = H;
59	        this->W = W;
60	        this->outH = outH;
61	        this->outW = outW;
62	        this->pt = pt;
63	        this->pb = pb;
64	        this->pl = pl;
65	        this->pr = pr;
66	        this->ncPerBlock = ncPerBlock;
67	        this->blockNum = blockNum;
68	
69	        goGM_.SetGlobalBuffer(
70	            reinterpret_cast<__gm__ dataType *>(grad_output),
71	            static_cast<uint64_t>(totalNc) * outH * outW);
72	        giGM_.SetGlobalBuffer(
73	            reinterpret_cast<__gm__ dataType *>(grad_input),
74	            static_cast<uint64_t>(totalNc) * H * W);
75	
76	        if ASCEND_IS_AIV { InitAivBuffers(); }
77	    }
78	
79	    __aicore__ inline void Process()
80	    {
81	        if ASCEND_IS_AIV {
82	            const int coreIdx = AscendC::GetBlockIdx();
83	            for (int localIdx = 0; localIdx < ncPerBlock; ++localIdx) {
84	                int nc = coreIdx * ncPerBlock + localIdx;
85	                if (nc >= totalNc) { break; }
86	                ProcessNc(nc);
87	            }
88	        }
89	    }
90	
91	private:
92	    __aicore__ inline void InitAivBuffers()
93	    {
94	        // Data queues for GM↔UB transfer
95	        pipe.InitBuffer(giInQueue_, BUFFER_NUM, W * sizeof(dataType));
96	        pipe.InitBuffer(goInQueue_, BUFFER_NUM, outW * sizeof(dataType));
97	        pipe.InitBuffer(giOutQueue_, BUFFER_NUM, W * sizeof(dataType));
98	
99	        // FP32 compute temp: goTmpBuf holds a sub-range of go (max outW float elements)
100	        pipe.InitBuffer(goTmpBuf_, outW * sizeof(float));
101	        // Reduce workspace and sum buffer
102	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
103	        pipe.InitBuffer(reduceWorkBuf_, static_cast<uint32_t>(outW) * sizeof(float));
104	
105	        // FP16/BF16 cast buffers (giFp32 accumulator, go fp32 input)
106	        if constexpr (!std::is_same_v<dataType, float>) {
107	            pipe.InitBuffer(goFp32Buf_, outW * sizeof(float));
108	        }
109	        // Always allocate a separate fp32 accumulator buffer.
110	        // Even for fp32, we can't reuse the TQue buffer (it gets freed before accumulation completes).
111	        pipe.InitBuffer(giFp32Buf_, W * sizeof(float));
112	    }
113	
114	    // -----------------------------------------------------------------------
115	    // Data transfer helpers
116	    // -----------------------------------------------------------------------
117	
118	    __aicore__ inline void CopyInGi(uint64_t nc, int32_t h)
119	    {
120	        giInLocal_ = giInQueue_.AllocTensor<dataType>();
121	        auto gmOffset = nc * static_cast<uint64_t>(H) * W + static_cast<uint64_t>(h) * W;
122	        LoadGmToUb(giInLocal_, giGM_[gmOffset], static_cast<uint32_t>(W));
123	        giInQueue_.EnQue(giInLocal_);
124	    }
125	
126	    __aicore__ inline void CopyInGo(uint64_t nc, int32_t oh)
127	    {
128	        goInLocal_ = goInQueue_.AllocTensor<dataType>();
129	        auto gmOffset = nc * static_cast<uint64_t>(outH) * outW + static_cast<uint64_t>(oh) * outW;
130	        LoadGmToUb(goInLocal_, goGM_[gmOffset], static_cast<uint32_t>(outW));
131	        goInQueue_.EnQue(goInLocal_);
132	    }
133	
134	    __aicore__ inline void CopyOutGi(uint64_t nc, int32_t h)
135	    {
136	        giOutLocal_ = giOutQueue_.DeQue<dataType>();
137	        auto gmOffset = nc * static_cast<uint64_t>(H) * W + static_cast<uint64_t>(h) * W;
138	        StoreUbToGm(giGM_[gmOffset], giOutLocal_, static_cast<uint32_t>(W));
139	        giOutQueue_.FreeTensor(giOutLocal_);
140	    }
141	
142	    // -----------------------------------------------------------------------
143	    // Cast helpers — convert dataType <-> float32 as needed
144	    // -----------------------------------------------------------------------
145	
146	    __aicore__ inline void PrepareFp32Accumulator(int32_t count)
147	    {
148	        giFp32Acc_ = giFp32Buf_.Get<float>();
149	        if constexpr (std::is_same_v<dataType, float>) {
150	            // Copy TQue data → giFp32Buf_ (separate TBuf, won't be freed)
151	            AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(count), 0, 0};
152	            AscendC::DataCopy(giFp32Acc_, giInLocal_, copyParams);
153	        } else {
154	            AscendC::Cast(giFp32Acc_, giInLocal_, AscendC::RoundMode::CAST_NONE, count);
155	            AscendC::PipeBarrier<PIPE_V>();
156	        }
157	    }
158	
159	    __aicore__ inline void PrepareFp32GoInput(int32_t count)
160	    {
161	        if constexpr (std::is_same_v<dataType, float>) {
162	            goFp32Input_ = goInLocal_.template ReinterpretCast<float>();
163	        } else {
164	            goFp32Input_ = goFp32Buf_.Get<float>();
165	            AscendC::Cast(goFp32Input_, goInLocal_, AscendC::RoundMode::CAST_NONE, count);
166	            AscendC::PipeBarrier<PIPE_V>();
167	        }
168	    }
169	
170	    __aicore__ inline void FinalizeAccumulator(int32_t count)
171	    {
172	        if constexpr (!std::is_same_v<dataType, float>) {
173	            AscendC::Cast(giOutLocal_, giFp32Acc_, AscendC::RoundMode::CAST_NONE, count);
174	        } else {
175	            AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(count), 0, 0};
176	            AscendC::DataCopy(giOutLocal_, giFp32Acc_, copyParams);
177	        }
178	        // Ensure V pipe has completed before EnQue for DMA
179	        AscendC::PipeBarrier<PIPE_V>();
180	    }
181	
182	    // -----------------------------------------------------------------------
183	    // Accumulation helpers
184	    // -----------------------------------------------------------------------
185	
186	    // Add interior section: giFp32Acc_[0:W] += goFp32Input_[pl:pl+W]
187	    __aicore__ inline void AddInterior()
188	    {
189	        AscendC::LocalTensor<float> goSlice = goTmpBuf_.Get<float>();
190	        AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(W),
191	                                            static_cast<uint16_t>(pl), 0};
192	        AscendC::DataCopy(goSlice, goFp32Input_, copyParams);
193	        AscendC::PipeBarrier<PIPE_V>();
194	
195	        AscendC::Add(giFp32Acc_, giFp32Acc_, goSlice, W);
196	    }
197	
198	    // Accumulate left pad: giFp32Acc_[0] += sum(goFp32Input_[0:pl])
199	    __aicore__ inline void AddLeftPad()
200	    {
201	        if (pl <= 0) { return; }
202	
203	        AscendC::LocalTensor<float> goSlice = goTmpBuf_.Get<float>();
204	        AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(pl), 0, 0};
205	        AscendC::DataCopy(goSlice, goFp32Input_, copyParams);
206	        AscendC::PipeBarrier<PIPE_V>();
207	
208	        reduceWorkLocal_ = reduceWorkBuf_.Get<float>();
209	        sumLocal_ = sumBuf_.Get<float>();
210	        AscendC::ReduceSum<float>(sumLocal_, goSlice, reduceWorkLocal_, pl);
211	        AscendC::PipeBarrier<PIPE_V>();
212	
213	        float padSum = sumLocal_.GetValue(0);
214	        AscendC::PipeBarrier<PIPE_ALL>();
215	
216	        float gi0Val = giFp32Acc_.GetValue(0);
217	        giFp32Acc_.SetValue(0, gi0Val + padSum);
218	    }
219	
220	    // Accumulate right pad: giFp32Acc_[W-1] += sum(goFp32Input_[pl+W:outW])
221	    __aicore__ inline void AddRightPad()
222	    {
223	        if (pr <= 0) { return; }
224	
225	        AscendC::LocalTensor<float> goSlice = goTmpBuf_.Get<float>();
226	        AscendC::DataCopyParams copyParams{1, static_cast<uint16_t>(pr),
227	                                            static_cast<uint16_t>(pl + W), 0};
228	        AscendC::DataCopy(goSlice, goFp32Input_, copyParams);
229	        AscendC::PipeBarrier<PIPE_V>();
230	
231	        reduceWorkLocal_ = reduceWorkBuf_.Get<float>();
232	        sumLocal_ = sumBuf_.Get<float>();
233	        AscendC::ReduceSum<float>(sumLocal_, goSlice, reduceWorkLocal_, pr);
234	        AscendC::PipeBarrier<PIPE_V>();
235	
236	        float padSum = sumLocal_.GetValue(0);
237	        AscendC::PipeBarrier<PIPE_ALL>();
238	
239	        float giLast = giFp32Acc_.GetValue(W - 1);
240	        giFp32Acc_.SetValue(W - 1, giLast + padSum);
241	    }
242	
243	    // -----------------------------------------------------------------------
244	    // Main computation
245	    // -----------------------------------------------------------------------
246	
247	    // Compute: accumulate one go row into gi accumulator
248	    __aicore__ inline void ComputeAccumulate()
249	    {
250	        goInLocal_ = goInQueue_.DeQue<dataType>();
251	        PrepareFp32GoInput(outW);
252	        AscendC::PipeBarrier<PIPE_ALL>();
253	
254	        AddInterior();
255	        AddLeftPad();
256	        AddRightPad();
257	
258	        goInQueue_.FreeTensor(goInLocal_);
259	        AscendC::PipeBarrier<PIPE_ALL>();
260	    }
261	
262	    // Process one gi row: load, accumulate all go contributions, write back
263	    __aicore__ inline void ProcessGiRow(uint64_t nc, int32_t h, int32_t ohStart, int32_t ohEnd)
264	    {
265	        // Step 1: Load gi row from GM, zero-init accumulator
266	        CopyInGi(nc, h);
267	        giInLocal_ = giInQueue_.DeQue<dataType>();
268	        PrepareFp32Accumulator(W);
269	
270	        // Zero the accumulator (gi starts at 0, F.pad with grad_input=0 gives zero grad at edges)
271	        AscendC::Duplicate(giFp32Acc_, 0.0f, W);
272	
273	        giInQueue_.FreeTensor(giInLocal_);
274	        AscendC::PipeBarrier<PIPE_ALL>();
275	
276	        // Step 2: Accumulate all contributing go rows
277	        for (int oh = ohStart; oh <= ohEnd; ++oh) {
278	            CopyInGo(nc, oh);
279	            ComputeAccumulate();
280	        }
281	
282	        // Step 3: Write back accumulated gi row to GM
283	        giOutLocal_ = giOutQueue_.AllocTensor<dataType>();
284	
285	        if constexpr (std::is_same_v<dataType, float>) {
286	            // fp32: giFp32Acc_ is a ReinterpretCast of giOutLocal_ (same memory)
287	            // Data is already in giOutLocal_ via the ReinterpretCast alias
288	        } else {
289	            FinalizeAccumulator(W);
290	        }
291	
292	        giOutQueue_.EnQue(giOutLocal_);
293	        CopyOutGi(nc, h);
294	    }
295	
296	    // Process a single (n,c) pair
297	    __aicore__ inline void ProcessNc(int32_t nc)
298	    {
299	        uint64_t nc64 = static_cast<uint64_t>(nc);
300	
301	        for (int h = 0; h < H; ++h) {
302	            // go rows that map to gi row h via clamp(oh-pt, 0, H-1):
303	            //   Top edge (h==0): go rows 0..pt all map to gi row 0
304	            //   Bottom edge (h==H-1): go rows pt+H-1..outH-1 all map to gi row H-1
305	            //   Interior: go row pt+h maps to gi row h
306	
307	            int ohStart, ohEnd;
308	            if (h == 0) {
309	                ohStart = 0;
310	                ohEnd = pt;  // includes go row at oh=pt (maps to h=0 via oh-pt=0)
311	            } else if (h == H - 1) {
312	                ohStart = pt + H - 1;
313	                ohEnd = outH - 1;
314	            } else {
315	                ohStart = pt + h;
316	                ohEnd = pt + h;
317	            }
318	
319	            ProcessGiRow(nc64, h, ohStart, ohEnd);
320	        }
321	    }
322	
323	private:
324	    int32_t totalNc = 0;
325	    int32_t H = 0;
326	    int32_t W = 0;
327	    int32_t outH = 0;
328	    int32_t outW = 0;
329	    int32_t pt = 0;
330	    int32_t pb = 0;
331	    int32_t pl = 0;
332	    int32_t pr = 0;
333	    int32_t ncPerBlock = 0;
334	    int32_t blockNum = 0;
335	
336	    AscendC::TPipe pipe;
337	    AscendC::GlobalTensor<dataType> goGM_;
338	    AscendC::GlobalTensor<dataType> giGM_;
339	
340	    // TQue for GM↔UB data transfer
341	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> giInQueue_;
342	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> goInQueue_;
343	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> giOutQueue_;
344	
345	    // TBuf for intermediate computation
346	    AscendC::TBuf<AscendC::TPosition::VECCALC> goTmpBuf_;
347	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
348	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceWorkBuf_;
349	    AscendC::TBuf<AscendC::TPosition::VECCALC> giFp32Buf_;
350	    AscendC::TBuf<AscendC::TPosition::VECCALC> goFp32Buf_;
351	
352	    // Local tensor handles
353	    AscendC::LocalTensor<dataType> giInLocal_;
354	    AscendC::LocalTensor<dataType> goInLocal_;
355	    AscendC::LocalTensor<dataType> giOutLocal_;
356	    AscendC::LocalTensor<float> giFp32Acc_;
357	    AscendC::LocalTensor<float> goFp32Input_;
358	    AscendC::LocalTensor<float> sumLocal_;
359	    AscendC::LocalTensor<float> reduceWorkLocal_;
360	};
361	
362	// =========================================================================
363	// Kernel entry point with dtype dispatch
364	// =========================================================================
365	
366	extern "C" __global__ __aicore__ void pad_v3_grad_replicate(
367	    GM_ADDR grad_output, GM_ADDR grad_input,
368	    int32_t totalNc, int32_t H, int32_t W, int32_t outH, int32_t outW,
369	    int32_t pt, int32_t pb, int32_t pl, int32_t pr,
370	    int32_t blockNum, int32_t ncPerBlock,
371	    int64_t dtypeFlag)
372	{
373	    if (dtypeFlag == 0) {
374	        PadV3GradReplicateKernel<float> kernel;
375	        kernel.Init(grad_output, grad_input, totalNc, H, W, outH, outW, pt, pb, pl, pr,
376	                    blockNum, ncPerBlock);
377	        kernel.Process();
378	    } else if (dtypeFlag == 1) {
379	        PadV3GradReplicateKernel<half> kernel;
380	        kernel.Init(grad_output, grad_input, totalNc, H, W, outH, outW, pt, pb, pl, pr,
381	                    blockNum, ncPerBlock);
382	        kernel.Process();
383	    } else {
384	        PadV3GradReplicateKernel<bfloat16_t> kernel;
385	        kernel.Init(grad_output, grad_input, totalNc, H, W, outH, outW, pt, pb, pl, pr,
386	                    blockNum, ncPerBlock);
387	        kernel.Process();
388	    }
389	}
